ALTER TABLE public.whispers_reports ADD COLUMN photo_count integer NOT NULL DEFAULT 0;
UPDATE public.whispers_reports r SET photo_count=(SELECT count(*) FROM public.whispers_records p WHERE p.report_id=r.id AND p.kind='photo');
ALTER TABLE public.whispers_records ADD COLUMN upload_id text;
CREATE UNIQUE INDEX whispers_photo_retry ON public.whispers_records(report_id,upload_id) WHERE upload_id IS NOT NULL;
CREATE OR REPLACE FUNCTION public.whispers_photo_limit() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.kind='photo' THEN UPDATE public.whispers_reports SET photo_count=photo_count+1 WHERE id=NEW.report_id AND workspace=NEW.workspace AND revoked_at IS NULL AND removal_requested_at IS NULL AND expires_at>now() AND photo_count<3; IF NOT FOUND THEN RAISE EXCEPTION 'Photo limit or inactive report'; END IF; ELSE PERFORM 1 FROM public.whispers_reports WHERE id=NEW.report_id AND workspace=NEW.workspace AND revoked_at IS NULL AND removal_requested_at IS NULL AND expires_at>now() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Inactive report'; END IF; END IF; RETURN NEW; END $$;
CREATE TABLE public.whispers_media_cleanup (report_id uuid PRIMARY KEY, queued_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.whispers_media_cleanup TO service_role;
ALTER TABLE public.whispers_media_cleanup ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.whispers_revoke_private(p_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM 1 FROM public.whispers_reports WHERE id=p_id FOR UPDATE; IF NOT FOUND THEN RETURN false; END IF; UPDATE public.whispers_reports SET body=jsonb_build_object('fictional',true,'removed',true),revoked_at=coalesce(revoked_at,now()),version=version+1 WHERE id=p_id; INSERT INTO public.whispers_media_cleanup(report_id) VALUES(p_id) ON CONFLICT DO NOTHING; DELETE FROM public.whispers_records WHERE report_id=p_id; DELETE FROM public.whispers_expert_requests WHERE p_id=ANY(report_ids); UPDATE public.whispers_updates SET state='withdrawn',body=jsonb_build_object('title','Withdrawn update','summary','','known','','uncertain','','sources','[]'::jsonb) WHERE p_id=ANY(source_report_ids); RETURN true; END $$;
REVOKE ALL ON FUNCTION public.whispers_revoke_private(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.whispers_revoke_private(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.whispers_expire_private() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r record; n integer:=0; BEGIN FOR r IN SELECT id FROM public.whispers_reports WHERE expires_at<=now() AND revoked_at IS NULL ORDER BY expires_at LIMIT 100 FOR UPDATE SKIP LOCKED LOOP PERFORM public.whispers_revoke_private(r.id); n:=n+1; END LOOP; RETURN n; END $$;
CREATE FUNCTION public.whispers_publication_transition(p_id uuid,p_actor uuid,p_action text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u public.whispers_updates; r public.whispers_reports; needed text; expected text; BEGIN needed:=CASE WHEN p_action='submit_update' THEN 'reviewer' ELSE 'publisher' END; SELECT * INTO u FROM public.whispers_updates WHERE id=p_id FOR UPDATE; IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=p_actor AND active AND role=needed AND u.workspace=ANY(contexts)) THEN RAISE EXCEPTION 'Access required'; END IF; expected:=CASE p_action WHEN 'submit_update' THEN 'draft' WHEN 'disclosure' THEN 'under_review' WHEN 'approve' THEN 'under_review' WHEN 'publish' THEN 'approved' WHEN 'withdraw' THEN 'published' ELSE NULL END; IF expected IS NULL OR u.state<>expected THEN RAISE EXCEPTION 'Publication state changed'; END IF; IF p_action IN ('disclosure','approve','publish') AND u.author_id=p_actor THEN RAISE EXCEPTION 'Independent reviewer required'; END IF; IF p_action IN ('approve','publish') THEN IF u.disclosure_reviewer_id IS NULL OR u.disclosure_reviewer_id=u.author_id THEN RAISE EXCEPTION 'Disclosure review required'; END IF; IF cardinality(u.source_report_ids)=0 THEN RAISE EXCEPTION 'Source required'; END IF; FOR r IN SELECT * FROM public.whispers_reports WHERE id=ANY(u.source_report_ids) ORDER BY id FOR UPDATE LOOP IF r.workspace<>u.workspace OR r.revoked_at IS NOT NULL OR r.removal_requested_at IS NOT NULL OR r.expires_at<=now() OR r.body->>'publicSummaryPermission' IS DISTINCT FROM 'true' OR r.body->>'sensitivity'='restricted' THEN RAISE EXCEPTION 'Source cannot be published'; END IF; END LOOP; IF (SELECT count(*) FROM public.whispers_reports WHERE id=ANY(u.source_report_ids))<>cardinality(u.source_report_ids) THEN RAISE EXCEPTION 'Source unavailable'; END IF; END IF; UPDATE public.whispers_updates SET state=CASE p_action WHEN 'submit_update' THEN 'under_review' WHEN 'approve' THEN 'approved' WHEN 'publish' THEN 'published' WHEN 'withdraw' THEN 'withdrawn' ELSE state END,disclosure_reviewer_id=CASE WHEN p_action='disclosure' THEN p_actor ELSE disclosure_reviewer_id END,approver_id=CASE WHEN p_action='approve' THEN p_actor ELSE approver_id END,publisher_id=CASE WHEN p_action='publish' THEN p_actor ELSE publisher_id END,published_at=CASE WHEN p_action='publish' THEN now() ELSE published_at END WHERE id=p_id; INSERT INTO public.whispers_audit(actor_id,action,workspace,target_id) VALUES(p_actor,p_action,u.workspace,u.id); RETURN true; END $$;
REVOKE ALL ON FUNCTION public.whispers_publication_transition(uuid,uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.whispers_publication_transition(uuid,uuid,text) TO service_role;
CREATE TABLE public.whispers_release_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL CHECK(kind IN ('translation','security','legal','safety')), reviewer_id uuid NOT NULL, reviewed_at timestamptz NOT NULL DEFAULT now(), reference text NOT NULL);
GRANT SELECT ON public.whispers_release_reviews TO authenticated;
GRANT ALL ON public.whispers_release_reviews TO service_role;
ALTER TABLE public.whispers_release_reviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_release_reviews ON public.whispers_release_reviews FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin' AND active));
COMMENT ON TABLE public.whispers_release_reviews IS 'Records human review references, not automatic certification. Intake remains fictional only.';
CREATE OR REPLACE VIEW public.whispers_public_updates AS SELECT id,CASE WHEN state='withdrawn' THEN 'Withdrawn update' ELSE body->>'title' END AS title,CASE WHEN state='withdrawn' THEN NULL ELSE body->>'summary' END AS summary,CASE WHEN state='withdrawn' THEN NULL ELSE body->>'known' END AS known,CASE WHEN state='withdrawn' THEN NULL ELSE body->>'uncertain' END AS uncertain,CASE WHEN state='withdrawn' THEN NULL ELSE body->'sources' END AS sources,published_at,state='withdrawn' AS withdrawn FROM public.whispers_updates WHERE state IN ('published','withdrawn') AND published_at IS NOT NULL;